import { test, expect } from '@playwright/test';

test.describe('PDF Inline Viewer', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should display uploaded PDF in inline viewer', async ({ page }) => {
    // Intercept the file upload API
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Upload a PDF file using getByLabel
    const uploadInput = page.getByLabel('Upload File');
    await uploadInput.fill('test.pdf');

    // Verify the file is uploaded by checking the preview button
    const previewButton = page.getByRole('button', { name: /preview/i });
    await expect(previewButton).toBeVisible();

    // Click the preview button to display the PDF
    await previewButton.click();

    // Verify the PDF is displayed in the inline viewer
    const viewer = page.getByRole('region', { name: /inline viewer/i });
    await expect(viewer).toBeVisible();

    // Verify the viewer contains the correct PDF content
    const pdfContent = page.locator('[data-testid="pdf-content"]');
    await expect(pdfContent).toContainText('test.pdf');

    // Verify the viewer has the correct file size
    const fileSize = page.getByText('File Size: 123 KB');
    await expect(fileSize).toBeVisible();

    // Verify the viewer has the correct file name
    const fileName = page.getByText('test.pdf');
    await expect(fileName).toBeVisible();

    // Verify the viewer has the correct file type
    const fileType = page.getByText('PDF');
    await expect(fileType).toBeVisible();

    // Verify the viewer has the correct file extension
    const fileExtension = page.getByText('pdf');
    await expect(fileExtension).toBeVisible();

    // Verify the viewer has the correct file icon
    const fileIcon = page.getByRole('img', { name: /pdf icon/i });
    await expect(fileIcon).toBeVisible();

    // Verify the viewer has the correct page count
    const pageCount = page.getByText('Page 1 of 1');
    await expect(pageCount).toBeVisible();
  });

  test('should handle empty file upload and display error message', async ({ page }) => {
    // Intercept the file upload API
    await page.route('**/api/upload', (route) => {
      route.abort();
    });

    // Upload an empty file using getByLabel
    const uploadInput = page.getByLabel('Upload File');
    await uploadInput.fill('');

    // Verify the preview button is disabled
    const previewButton = page.getByRole('button', { name: /preview/i });
    await expect(previewButton).toBeDisabled();

    // Verify the error message is displayed
    const errorMessage = page.getByText(/File is empty/i);
    await expect(errorMessage).toBeVisible();

    // Verify the viewer is not displayed
    const viewer = page.getByRole('region', { name: /inline viewer/i });
    await expect(viewer).not.toBeVisible();

    // Verify the file name and file type are not displayed
    const fileName = page.getByText('test.pdf');
    await expect(fileName).not.toBeVisible();

    const fileType = page.getByText('PDF');
    await expect(fileType).not.toBeVisible();

    // Verify the file size is not displayed
    const fileSize = page.getByText('File Size: 0 KB');
    await expect(fileSize).not.toBeVisible();
  });
});
